import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { SESSION_COOKIE, verifySession } from "@/agent/lib/session";

// Paths reachable without signing in. /eve/* is excluded from the matcher below:
// the agent verifies the same cookie itself in agent/channels/eve.ts.
const PUBLIC_PATHS = ["/login"];

export async function proxy(request: NextRequest) {
  // Generated by eve: keeps `vercel dev` requests on the dev router host.
  const routerHost = process.env.VERCEL_URL;
  const forwardedHost = request.headers.get("x-forwarded-host");
  if (process.env.__VERCEL_DEV_RUNNING === "1" && routerHost && forwardedHost !== routerHost) {
    const target = request.nextUrl.clone();
    target.protocol = "http:";
    target.host = routerHost;
    return NextResponse.redirect(target);
  }

  // Every dashboard page and the chat UI need a valid session. Pages still check
  // the role themselves; this is only the "are you signed in at all" gate.
  if (!PUBLIC_PATHS.includes(request.nextUrl.pathname)) {
    const viewer = await verifySession(request.cookies.get(SESSION_COOKIE)?.value);
    if (!viewer) {
      const login = request.nextUrl.clone();
      login.pathname = "/login";
      login.search = "";
      return NextResponse.redirect(login);
    }
  }
  return NextResponse.next();
}

export const config = {
  matcher: ["/((?!eve/|_next/|icon|apple-icon|favicon).*)"],
};
